import type { ComponentProps } from "@types";
import type { CSSObject } from "@emotion/react";

export enum SliderAriaLabel {
  Thumb = "thumb",
  ThumbMin = "thumbMin",
  ThumbMax = "thumbMax",
}

// Props for the slider component
export type SliderProps = ComponentProps & {
  behavior?: "single" | "range";
  rangeMin?: number;
  dir?: "ltr" | "rtl";
  rangeMax?: number;
  name?: string;
  value?: number[];
  step?: number;
  defaultValue?: number;
  defaultMinValue?: number;
  defaultMaxValue?: number;
  onValueChange?: (value: number[]) => void;
  getItemAriaLabel?: (label: SliderAriaLabel) => string | undefined;
  disabled?: boolean;
  className?: string;
  styleSlots?: {
    root?: CSSObject;
    track?: CSSObject;
    trackDisabled?: CSSObject;
    thumb?: CSSObject;
    thumbHover?: CSSObject;
    thumbPressed?: CSSObject;
    thumbDisabled?: CSSObject;
    thumbFocus?: CSSObject;
    range?: CSSObject;
    rangeDisabled?: CSSObject;
    disabled?: CSSObject;
    sliderRoot?: CSSObject;
    labelContainer?: CSSObject;
    labelMax?: CSSObject;
    labelMin?: CSSObject;
  };
};
